package com.videokit.spike.e4;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.*;
/** Boundary tests call actual production IO guards, without creating a permanently unresolved live socket. */
public final class JCheck {
 static final class CountIn extends ByteArrayInputStream {int calls,bytes,lastRequested;CountIn(int n){super(new byte[n]);}public synchronized int read(byte[] b,int o,int n){calls++;lastRequested=n;int r=super.read(b,o,n);if(r>0)bytes+=r;return r;}}
 static void boundary(Path p)throws Exception{E13JSocket o=new E13JSocket(p,E13JIdentity.INVENTORY);CountIn in=new CountIn(E13JSocket.WIRE_CAP+4096);byte[] block=new byte[4096];while(o.chargedWire<E13JSocket.WIRE_CAP)o.readSome(in,block,block.length);ICheck.need(in.bytes==70656&&o.chargedWire==70656&&in.lastRequested==1024,"exact application read allowance");int before=in.calls;try{o.readSome(in,block,1);throw new AssertionError("overread allowed");}catch(IOException expected){}o.drain(in);ICheck.need(in.calls==before&&in.bytes==70656&&o.budgetUnknown&&!o.socket.returned()&&E13JSocket.OWNERS.contains(o),"zero read after limit including drain/EOF; same holder unknown");ICheck.need(!o.allocateEntered&&!o.reader.isAlive()&&!o.keeper.isAlive(),"non-network guard fixture no thread/socket ever started");System.out.println("PASS BUDGET_BOUNDARY actualProductionReadGuard=true rx=70656 afterLimitReadCalls=0 noEofProbe=true holderUnknownRetained=true liveSocketCreated=false");}
 static void tx(Path p)throws Exception{E13JSocket o=new E13JSocket(p,E13JIdentity.INVENTORY);AtomicInteger writes=new AtomicInteger(),bytes=new AtomicInteger();OutputStream out=new OutputStream(){public void write(int n){writes.incrementAndGet();bytes.incrementAndGet();}public void write(byte[] b){writes.incrementAndGet();bytes.addAndGet(b.length);}};o.chargedWire=70654;o.send(out,new byte[]{1,2});int before=writes.get();try{o.send(out,new byte[]{3});throw new AssertionError("TX beyond remaining");}catch(IOException expected){}ICheck.need(o.chargedWire==70656&&o.intendedTx==2&&writes.get()==before&&bytes.get()==2&&o.writesEntered==1&&o.writesReturned==1&&o.budgetUnknown,"no TX intent/IO after remaining consumed");E13JSocket mixed=new E13JSocket(p.resolve("mixed"),E13JIdentity.INVENTORY);mixed.chargedWire=70655;CountIn in=new CountIn(8);mixed.readSome(in,new byte[4096],4096);ICheck.need(in.bytes==1&&in.lastRequested==1,"remaining-one read length exact");int calls=in.calls;try{mixed.readSome(in,new byte[1],1);}catch(IOException expected){}ICheck.need(in.calls==calls&&mixed.chargedWire==70656,"no implicit EOF read");System.out.println("PASS BUDGET_TX actualProductionWriteGuard=true exact70656=true readLengthLeRemaining=true noLiveIOFixture=true");}
 static void productionAudit(Path p)throws Exception{List<ICheck.Peer> peers=new ArrayList<>();AtomicInteger calls=new AtomicInteger();E13JReadOnly.Batch batch=new E13JReadOnly.Batch(p,new E13JReadOnly.Factory(){public E13JSocket create(Path d,String script)throws Exception{int n=calls.incrementAndGet();ICheck.Peer peer=new ICheck.Peer("OK",script,n==1?IFixtures.inventory():IFixtures.identity());peers.add(peer);return new E13JSocket(d,script,"127.0.0.1",peer.listener.getLocalPort(),x->{},null);}public long qualification(){return E13JSocket.QUALIFICATION;}});try{batch.run();}finally{for(ICheck.Peer peer:peers)peer.close();for(E13JSocket o:batch.originals){o.reader.join();o.keeper.join();}batch.keeper.join();}ICheck.need(calls.get()==2&&batch.reservations==262144&&!batch.failed,"real production batch budget and success");for(int i=0;i<2;i++){E13JSocket o=batch.originals.get(i);Path root=p.resolve("query-"+(i+1));String raw=Files.readString(root.resolve("facts.txt"));ICheck.need(raw.contains("phase=T")&&raw.contains("cw="+o.chargedWire)&&raw.contains("in="+o.incomingWire)&&raw.contains("tx="+o.intendedTx)&&raw.contains("we=3 wr=3")&&raw.contains("auditOwnClose=UNPROVEN")&&raw.contains("qualification=SNAPSHOT_NOT_FINAL"),"production owns persisted exact audit, snapshot not final ACK");ICheck.need(Files.size(root.resolve("facts.txt"))<=1024&&Files.size(root.resolve("intent.txt"))<=1024&&o.chargedWire==o.incomingWire+o.intendedTx&&Files.size(root.resolve("original.wire"))==o.chargedWire,"actual production counters and file bytes bind");ICheck.need(!Files.exists(root.resolve("final-owner-facts.txt")),"no harness facts required");}System.out.println("PASS PRODUCTION_AUDIT actualBatchOpArchiveProducer=true noICheckFacts=true budget262144=true metadataLe2048Each=true");}
 public static void main(String[] a)throws Exception{Path p=Paths.get(a[1]);Files.createDirectories(p);switch(a[0]){case "BUDGET_BOUNDARY":boundary(p);break;case "BUDGET_TX":tx(p);break;case "PRODUCTION_AUDIT":productionAudit(p);break;default:throw new AssertionError(a[0]);}}
}
